      "limits": "Experimental forward mode for scalar functions. Reverse mode and array-valued functions are planned.",
      "files": {
        "lab/main.ostrin": "// Scientific Lab · Autodiff\n// Forward-mode derivatives with dual numbers from the `autodiff` package, then Newton's method.\nimport autodiff.autodiff\nimport autodiff.autodiff.{Dual}\n\nfn cubic(x: Dual) -> Dual {\n    // f(x) = x^3 - 2x - 5\n    x * x * x - 2.0 * x - autodiff.constant(5.0)\n}\n\nfn three(x: Float) -> String {\n    (round(x * 1000.0) / 1000.0).to_string()\n}\n\nfn main() -> Void {\n    start = 3.0\n    for i in 0 to 8 {\n        x = (i as Float) * 0.5 - 1.0\n        print(\"point \" + three(x) + \" \" + three(autodiff.value(cubic, x)) + \" \" + three(autodiff.derivative(cubic, x)))\n    }\n    root = autodiff.newton(cubic, start, 8)\n    print(\"newton from \" + three(start) + \": root = \" + (round(root * 1000000.0) / 1000000.0).to_string())\n    print(\"|f(root)| = \" + three(abs(autodiff.value(cubic, root))) + \", f'(root) = \" + three(autodiff.derivative(cubic, root)))\n}\n",
        "lab/ostrin.toml": "[package]\nname = \"autodiff_lab\"\nversion = \"0.1.0\"\nentry = \"main.ostrin\"\n\n[dependencies]\nautodiff = { path = \"../autodiff\" }\n",
        "autodiff/autodiff.ostrin": "// Diferenciación automática hacia adelante con números duales: (v, d) = (valor, derivada).\n// Los operadores + - * / funcionan sobre Dual (impl Add/Sub/Mul/Div).\npub record Dual {\n    v: Float\n    d: Float\n}\n\n// Con un escalar a la izquierda (2.0 * x, 1.0 - x): métodos reflejados; -x: neg.\nimpl Dual {\n    fn neg(self) -> Dual { Dual { v: 0.0 - self.v, d: 0.0 - self.d } }\n    fn radd(self, k: Float) -> Dual { Dual { v: k + self.v, d: self.d } }\n    fn rsub(self, k: Float) -> Dual { Dual { v: k - self.v, d: 0.0 - self.d } }\n    fn rmul(self, k: Float) -> Dual { Dual { v: k * self.v, d: k * self.d } }\n    fn rdiv(self, k: Float) -> Dual { Dual { v: k / self.v, d: 0.0 - k * self.d / (self.v * self.v) } }\n}\n\npub fn constant(c: Float) -> Dual { Dual { v: c, d: 0.0 } }\npub fn variable(x: Float) -> Dual { Dual { v: x, d: 1.0 } }\n\nimpl Add for Dual {\n    fn add(self, b: Self) -> Self { Dual { v: self.v + b.v, d: self.d + b.d } }\n}\n\nimpl Sub for Dual {\n    fn sub(self, b: Self) -> Self { Dual { v: self.v - b.v, d: self.d - b.d } }\n}\n\nimpl Mul for Dual {\n    fn mul(self, b: Self) -> Self { Dual { v: self.v * b.v, d: self.d * b.v + self.v * b.d } }\n}\n\nimpl Div for Dual {\n    fn div(self, b: Self) -> Self { Dual { v: self.v / b.v, d: (self.d * b.v - self.v * b.d) / (b.v * b.v) } }\n}\n\npub fn scale(k: Float, a: Dual) -> Dual { Dual { v: k * a.v, d: k * a.d } }\npub fn powi(a: Dual, n: Int) -> Dual {\n    mut r = constant(1.0)\n    mut i = 0\n    while i < n {\n        r = r * a\n        i = i + 1\n    }\n    r\n}\npub fn dsin(a: Dual) -> Dual { Dual { v: sin(a.v), d: cos(a.v) * a.d } }\npub fn dcos(a: Dual) -> Dual { Dual { v: cos(a.v), d: 0.0 - sin(a.v) * a.d } }\npub fn dexp(a: Dual) -> Dual { Dual { v: exp(a.v), d: exp(a.v) * a.d } }\npub fn dln(a: Dual) -> Dual { Dual { v: ln(a.v), d: a.d / a.v } }\npub fn dsqrt(a: Dual) -> Dual { Dual { v: sqrt(a.v), d: a.d / (2.0 * sqrt(a.v)) } }\n\n/// f'(x) para una función escrita con las operaciones de este paquete.\npub fn derivative(f: fn(Dual) -> Dual, x: Float) -> Float {\n    f(variable(x)).d\n}\n\npub fn value(f: fn(Dual) -> Dual, x: Float) -> Float {\n    f(variable(x)).v\n}\n\n/// Gradiente de f(x, y): una pasada hacia adelante por variable.\npub fn gradient2(f: fn(Dual, Dual) -> Dual, x: Float, y: Float) -> List<Float> {\n    dx = f(variable(x), constant(y)).d\n    dy = f(constant(x), variable(y)).d\n    [dx, dy]\n}\n\n/// Método de Newton con derivada exacta.\npub fn newton(f: fn(Dual) -> Dual, start: Float, steps: Int) -> Float {\n    mut x = start\n    mut i = 0\n    while i < steps {\n        r = f(variable(x))\n        x = x - r.v / r.d\n        i = i + 1\n    }\n    x\n}\n",
        "autodiff/ostrin.toml": "[package]\nname = \"autodiff\"\nversion = \"0.1.0\"\nentry = \"autodiff.ostrin\"\n"
      },
