        "main.ostrin": "// Scientific Lab · Data\n// Parse CSV measurements, group them by station and summarize each group.\nfn main() -> Void {\n    text = \"station,temp_c,rain_mm\\nLima,21.5,0.0\\nCusco,12.0,3.5\\nLima,23.5,0.5\\nCusco,10.0,4.5\\nQuito,15.5,2.0\\nQuito,14.0,6.5\\nLima,22.0,0.2\\n\"\n    rows = parse_csv(text)\n    header = rows[0]\n    print(\"columns: \" + header.join(\", \"))\n\n    mut temps = Map<String, List<Float>>()\n    mut order: List<String> = []\n    mut i = 1\n    while i < rows.length() {\n        row = rows[i]\n        station = row[0]\n        match row[1].to_float() {\n            Ok(value) => {\n                if not temps.contains_key(station) {\n                    temps.set(station, [])\n                    order.push(station)\n                }\n                mut values = temps.get(station).unwrap()\n                values.push(value)\n                temps.set(station, values)\n            },\n            Err(message) => print(\"skipped row \" + i.to_string() + \": \" + message),\n        }\n        i = i + 1\n    }\n\n    for station in order {\n        values = array(temps.get(station).unwrap())\n        print(station + \": n=\" + values.length().to_string() + \" mean=\" + (round(values.mean() * 100.0) / 100.0).to_string() + \" min=\" + values.min().to_string() + \" max=\" + values.max().to_string())\n    }\n    print(\"stations: \" + order.length().to_string() + \", rows: \" + (rows.length() - 1).to_string())\n}\n"
