      "files": {
        "main.ostrin": "// Scientific Lab · Concurrency\n// Integrate sin(x) on [0, pi] with the midpoint rule, split across tasks joined by a channel.\nfn partial(start: Int, stop: Int, n: Int) -> Float {\n    h = pi() / (n as Float)\n    mut total = 0.0\n    for i in start until stop {\n        total = total + sin(((i as Float) + 0.5) * h) * h\n    }\n    total\n}\n\nfn main() -> Void {\n    workers = 4\n    intervals = 4000\n    results = channel<Float>()\n    chunk = intervals / workers\n\n    mut tasks: List<Task<Void>> = []\n    for w in 0 until workers {\n        start = w * chunk\n        stop = if w == workers - 1 { intervals } else { start + chunk }\n        tasks.push(spawn {\n            results.send(partial(start, stop, intervals))\n        })\n    }\n\n    mut total = 0.0\n    for w in 0 until workers {\n        value = results.receive().unwrap()\n        print(\"partial \" + w.to_string() + \" = \" + (round(value * 1000000.0) / 1000000.0).to_string())\n        total = total + value\n    }\n    for task in tasks {\n        task.join()\n    }\n    print(\"integral ≈ \" + (round(total * 1000000.0) / 1000000.0).to_string() + \" (exact 2)\")\n}\n"
      },
